    public void onCreate(Bundle state){super.onCreate(state);TimerLocks.grantUpdatePasses(this);tab=getIntent().getStringExtra("screen")==null?"Home":getIntent().getStringExtra("screen");if(state!=null){tab=state.getString("tab","Home");if(tab.equals("Goals"))tab="Timers";from=state.getString("from",from);to=state.getString("to",to);}getWindow().setStatusBarColor(GREEN);getWindow().setNavigationBarColor(BG);show();if(state==null&&!settings().getBoolean("guide_seen",false)){settings().edit().putBoolean("guide_seen",true).apply();handler.post(()->guide(0));}}
    private void guide(int step){settings().edit().putBoolean("guide_active",true).putBoolean("guide_interactive_seen",true).putInt("guide_step",Math.max(0,Math.min(6,step))).apply();go("Guide");}
    private void finishGuide(){settings().edit().putBoolean("guide_active",false).apply();go("Home");}
    private void guideHint(){LinearLayout c=card();utility(c,"Continue setup guide","Return to your current step · you can skip anytime","leaf",()->go("Guide"));button(c,"Skip setup for now",this::finishGuide);}
    private void setupGuide(){
        int step=Math.max(0,Math.min(6,settings().getInt("guide_step",0)));
        String[] names={"Welcome","Usage access","Automatic closing","Content protection","Daily app timer","Cooldowns","History & reminders"};
        String[] glyphs={"leaf","chart","clock","shield","clock","clock","bell"};
        heading("YOUR SETUP · STEP "+(step+1)+" OF 7",names[step],"Take action here, then return to check your setup. Every step is optional.");
        LinearLayout dots=new LinearLayout(this);for(int i=0;i<7;i++){final int target=i;TextView dot=title(""+(i+1),12,i==step?Color.WHITE:GREEN);dot.setGravity(Gravity.CENTER);dot.setBackground(shape(i==step?GREEN:SOFT,14));dot.setContentDescription("Step "+(i+1)+": "+names[i]);dot.setFocusable(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(36),1);p.setMargins(0,0,dp(5),dp(14));dots.addView(dot,p);dot.setOnClickListener(v->guide(target));}body.addView(dots);
        LinearLayout c=card();cardHeading(c,names[step],glyphs[step]);
        if(step==0){note(c,"Free, open source and without ads. Build healthier digital habits with app timers, porn and escort domain protection, private usage Insights and a charging clock.");LinearLayout preview=column();preview.setPadding(dp(16),dp(14),dp(16),dp(14));preview.setBackground(shape(SOFT,18));preview.addView(new Landscape(this),new LinearLayout.LayoutParams(-1,dp(70)));preview.addView(title("Choose your tools. Keep your pace.",19,GREEN));note(preview,"Use the buttons below each step to configure the real feature. The guide checks available permissions when you return.");c.addView(preview);note(c,"Your usage history stays on this phone. DNS and list downloads use external services, described in Settings → Privacy policy. Existing settings and timers are preserved.");}
        else if(step==1){boolean allowed=History.access(this);pill(c,allowed?"Usage access is allowed":"Usage access is not allowed",allowed);note(c,"This permission lets Badilika total app time and show usage reports.");guideInstruction(c,"1","Open Android Usage access using the button.");guideInstruction(c,"2","Select Badilika and turn Allow usage access on.");guideInstruction(c,"3","Press Android Back to return. This status updates automatically.");button(c,"Open Usage access settings",()->open(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));}
        else if(step==2){boolean allowed=AppLimitService.enforcing(this);pill(c,allowed?"Automatic closing is enabled":"Automatic closing needs setup",allowed);note(c,"At a daily app limit, Badilika returns the selected app to Home. It does not force-stop background playback.");guideInstruction(c,"1","First allow Usage access in the previous step.");guideInstruction(c,"2","Tap Enable automatic closing and read the permission explanation.");guideInstruction(c,"3","In Android Accessibility, choose Badilika's daily timers service and turn it on. Return with Back.");button(c,"Enable automatic closing",this::enableLimits);button(c,"Open Badilika app settings",()->open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));note(c,"If Android shows a restricted-setting warning, some phones provide App info → menu → Allow restricted settings. Only enable permissions you understand.");}
        else if(step==3){boolean porn=new LockState(this,"porn").enabled(),escort=new LockState(this,"escort").enabled();pill(c,porn?"Porn category enabled":"Porn category not enabled",porn);pill(c,escort?"Escort category enabled":"Escort category not enabled",escort);pill(c,GuardService.active?"Protection VPN connected":"VPN connection needed for filtering",GuardService.active);guideInstruction(c,"1","Open Protect. Choose porn protection, escort protection, or both.");guideInstruction(c,"2","Accept Android's VPN request and check that protection says connected.");guideInstruction(c,"3","Choose each category's disable delay. Minimum one full day; maximum 30 days.");button(c,"Open Protect and choose categories",()->go("Protect"));button(c,"Open Android VPN settings",()->open(new Intent("android.settings.VPN_SETTINGS")));button(c,"Open network settings",()->open(new Intent(Settings.ACTION_WIRELESS_SETTINGS)));note(c,"For best DNS coverage, turn off system Private DNS and browser Secure DNS. Their locations vary by phone/browser. Only one VPN can run at a time. Do not enable Block connections without VPN for this DNS-only service.");}
        else if(step==4){List<String> apps=TimerLocks.limited(this);pill(c,apps.size()+" apps have a daily allowance",!apps.isEmpty());LinearLayout sample=column();sample.setPadding(dp(16),dp(16),dp(16),dp(16));sample.setBackground(shape(SOFT,18));sample.addView(icon("clock",GREEN,32));sample.addView(title("00 : 30",32,GREEN));note(sample,"HOURS : MINUTES · Example: 30 minutes each day");c.addView(sample);guideInstruction(c,"1","Tap Choose an app and select the app you want to limit.");guideInstruction(c,"2","Tap its daily allowance clock. Choose hours, then minutes, just like an alarm.");guideInstruction(c,"3","Choose daily or enable a repeating window, then save. Daily timers count earlier usage today.");button(c,"Choose an app and set a timer",()->{go("Timers");pickApp();});button(c,"Open my app timers",()->go("Timers"));note(c,"00:30 is a duration, not 12:30 AM. Usage access and automatic closing must be enabled for enforcement.");}
        else if(step==5){note(c,"A cooldown gives you time to reconsider before loosening a boundary. This guide never starts or cancels a countdown for you.");guideInstruction(c,"1","For an app, open its timer editor and tap Choose cooldown. Leave days at 0 for a short wait, then choose hours and minutes.");guideInstruction(c,"2","For protection, open Protect and choose the category's disable delay.");guideInstruction(c,"3","To loosen or remove a limit, request its cooldown, wait, return and confirm. Cancel the request to keep the limit.");button(c,"Open app timers and cooldowns",()->go("Timers"));button(c,"Open protection disable delays",()->go("Protect"));note(c,"Reducing app time applies immediately. Increasing or removing it requires the wait. Protection stays on throughout its countdown and until confirmation. Powered-off time does not count. Android settings can still revoke permissions or uninstall the app.");}
        else {boolean tracking=settings().getBoolean("tracking",false);boolean notifications=Build.VERSION.SDK_INT>=24?getSystemService(NotificationManager.class).areNotificationsEnabled():true;pill(c,tracking?"History tracking is enabled":"History tracking is off",tracking);pill(c,notifications?"Notifications are available":"Notifications are off",notifications);guideInstruction(c,"1","Start tracking to save longer-term daily history and receive reminders.");guideInstruction(c,"2","Allow notifications when asked. Check battery settings if your phone stops background activity.");guideInstruction(c,"3","Open Insights to explore app time and Wi-Fi/mobile data by date.");button(c,tracking?"Open Insights":"Start tracking",()->{if(tracking)go("Insights");else startTracking();});button(c,"Set up notifications",()->{if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},33);else open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));});button(c,"Open app battery and permission settings",()->open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));note(c,"You can reopen this complete walkthrough anytime in Settings → Setup guide.");}
        LinearLayout actions=card();if(step>0)button(actions,"Previous step",()->guide(step-1));button(actions,step==6?"Finish setup guide":"Next step",()->{if(step==6)finishGuide();else guide(step+1);});button(actions,"Skip setup for now",this::finishGuide);
    }
    private void guideInstruction(LinearLayout c,String number,String instruction){LinearLayout row=new LinearLayout(this);row.setPadding(0,dp(10),0,dp(4));TextView badge=title(number,13,GREEN);badge.setGravity(Gravity.CENTER);badge.setBackground(shape(SOFT,12));row.addView(badge,new LinearLayout.LayoutParams(dp(30),dp(30)));TextView description=text(instruction,13,INK);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(12),0,0,0);row.addView(description,p);c.addView(row);}

